head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onrownumclick]<br/>focusDefaultColumn=true, rowStatusVisible=true 일때 RowNum Column 의 Body 영역 Cell 을 클릭 시 발생합니다.",
    "validation" : [
        "RowNum Column 의 Body 영역 Cell 을 클릭할 때 onrownumclick 이벤트가 발생해야 합니다.",
        "rowIndex 파라미터로 클릭된 Cell 의 Row 인덱스값이 전달되어야 합니다.",
        "focusDefaultColumn=true, rowNumVisible=true 조건에서 동작해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
        focusDefaultColumn: "true",
        rowNumVisible: "true",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onrownumclick"]);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



scwin.target1_onrownumclick = function (rowIndex) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onrownumclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("rowIndex : " + rowIndex);
}
